function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 100000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 0 || v >= 2 ** 30)) return 'Each value is an integer from 0 to 2^30 - 1.';
  if (!Number.isInteger(k) || k < 0 || k >= nums.length) return 'k must be at least 0 and less than nums.length.';
  return null;
}

