function minOrAfterOperations(nums, k) {
  let answer = 0;
  let mask = 0;
  for (let bit = 29; bit >= 0; bit--) {
    mask |= 1 << bit;
    let operations = 0;
    let current = mask;
    for (const num of nums) {
      current &= num;
      if ((current & mask) === 0) {
        current = mask;
      } else {
        operations++;
      }
    }
    if (operations > k) {
      mask ^= 1 << bit;
      answer |= 1 << bit;
    }
  }
  return answer;
}

