function minOrAfterOperations(nums, k) {
  // Every result is a split of nums into contiguous groups; a split into g groups costs n - g operations.
  const n = nums.length;
  let best = Infinity;
  for (let cuts = 0; cuts < 1 << (n - 1); cuts++) {
    let groups = 1;
    for (let b = 0; b < n - 1; b++) if (cuts & (1 << b)) groups++;
    if (n - groups > k) continue;
    let total = 0, part = nums[0];
    for (let i = 1; i < n; i++) {
      if (cuts & (1 << (i - 1))) { total |= part; part = nums[i]; }
      else part &= nums[i];
    }
    total |= part;
    best = Math.min(best, total);
  }
  return best;
}

