function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 10);
  const bits = size === 'large' ? 30 : [3, 4, 5, 30][Math.floor(rand() * 4)];
  const limit = 2 ** bits;
  const common = Math.floor(rand() * limit);
  const shareChance = rand();
  const nums = Array.from({ length: n }, () => {
    let value = Math.floor(rand() * limit);
    if (rand() < shareChance) value |= common;
    return value;
  });
  const mode = rand();
  let k;
  if (mode < 0.15) k = 0;
  else if (mode < 0.3) k = n - 1;
  else if (mode < 0.6) k = Math.floor(rand() * Math.max(1, Math.floor(n / 4)));
  else k = Math.floor(rand() * n);
  return [nums, k];
}
